export type SinkError =
  | {
      DuplicateEvent: {
        /**
         * The repeated id.
         */
        id: string;
      };
    }
  | {
      DuplicateObject: {
        /**
         * The repeated id.
         */
        id: string;
      };
    }
  | {
      IdTypeCollision: {
        /**
         * The contested id.
         */
        id: string;
      };
    }
  | {
      UnknownType: {
        /**
         * `"event"` or `"object"`.
         */
        kind: string;
        /**
         * The undeclared type name.
         */
        name: string;
      };
    }
  | "InvalidRef"
  | {
      Backend: string;
    };

export type SplitKind =
  | {
      /**
       * The separator.
       */
      delimiter: string;
      type: "delimiter";
    }
  | {
      /**
       * The pattern.
       */
      pattern: string;
      type: "regex";
    };

export type Target =
  | {
      /**
       * Event attributes.
       */
      attributes?: AttributeMapping[];
      /**
       * Event type.
       */
      event_type:
        | {
            /**
             * Column name.
             */
            column: string;
            type: "column";
          }
        | {
            type: "constant";
            /**
             * The value.
             */
            value: string;
          }
        | {
            /**
             * The template.
             */
            template: string;
            type: "template";
          }
        | {
            /**
             * Parts, tried in order.
             */
            parts: ValueExpression[];
            type: "coalesce";
          };
      /**
       * Event id. `None` assigns a UUID, which is not reproducible across runs and cannot
       * be compiled to a view.
       *
       * It is also what coalesces a fan-out: over a join of orders and their items, a `None`
       * id makes one event per item, an id naming the order one event per order, still related
       * to every item. The repeated rows count as
       * [`MappingStats::deduplicated`](super::report::MappingStats::deduplicated) while
       * `objects` below is emitted for each.
       */
      id?: ValueExpression | null;
      /**
       * Objects related to this event.
       */
      objects?: InlineObjectRef[];
      /**
       * When it happened.
       */
      timestamp:
        | {
            /**
             * How to read it. `None` means auto-detection.
             */
            format?: TimestampFormat | null;
            /**
             * Produces one text value from a row.
             *
             * Used by every position that becomes an identity: entity ids, relation endpoints, type names
             * and qualifiers. Every variant propagates absence, so if any input has no
             * [`Value::canonical_string`] the whole expression is `None` and the caller drops the row.
             */
            source:
              | {
                  /**
                   * Column name.
                   */
                  column: string;
                  type: "column";
                }
              | {
                  type: "constant";
                  /**
                   * The value.
                   */
                  value: string;
                }
              | {
                  /**
                   * The template.
                   */
                  template: string;
                  type: "template";
                }
              | {
                  /**
                   * Parts, tried in order.
                   */
                  parts: ValueExpression[];
                  type: "coalesce";
                };
            type: "value";
          }
        | {
            /**
             * Where the date comes from, if anywhere.
             */
            date?: TimestampPart | null;
            /**
             * Where the time comes from, if anywhere.
             */
            time?: TimestampPart | null;
            type: "components";
          };
      type: "event";
    }
  | {
      /**
       * Object attributes.
       */
      attributes?: AttributeMapping[];
      /**
       * Produces one text value from a row.
       *
       * Used by every position that becomes an identity: entity ids, relation endpoints, type names
       * and qualifiers. Every variant propagates absence, so if any input has no
       * [`Value::canonical_string`] the whole expression is `None` and the caller drops the row.
       */
      id:
        | {
            /**
             * Column name.
             */
            column: string;
            type: "column";
          }
        | {
            type: "constant";
            /**
             * The value.
             */
            value: string;
          }
        | {
            /**
             * The template.
             */
            template: string;
            type: "template";
          }
        | {
            /**
             * Parts, tried in order.
             */
            parts: ValueExpression[];
            type: "coalesce";
          };
      /**
       * Produces one text value from a row.
       *
       * Used by every position that becomes an identity: entity ids, relation endpoints, type names
       * and qualifiers. Every variant propagates absence, so if any input has no
       * [`Value::canonical_string`] the whole expression is `None` and the caller drops the row.
       */
      object_type:
        | {
            /**
             * Column name.
             */
            column: string;
            type: "column";
          }
        | {
            type: "constant";
            /**
             * The value.
             */
            value: string;
          }
        | {
            /**
             * The template.
             */
            template: string;
            type: "template";
          }
        | {
            /**
             * Parts, tried in order.
             */
            parts: ValueExpression[];
            type: "coalesce";
          };
      /**
       * When the attribute values below were observed. `None` records them as static
       * values stamped at the Unix epoch.
       */
      timestamp?: TimestampSource | null;
      type: "object";
    }
  | {
      event: EventEndpoint;
      object: ObjectEndpoint;
      /**
       * Relation qualifier.
       */
      qualifier?: ValueExpression | null;
      type: "e2o";
    }
  | {
      /**
       * Relation qualifier.
       */
      qualifier?: ValueExpression | null;
      source: ObjectEndpoint;
      target: ObjectEndpoint;
      type: "o2o";
    };
